CREATE TABLE IF NOT EXISTS detection_locks (source_ip VARCHAR(45) PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_alerts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT UNSIGNED NOT NULL, message TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'recorded', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(incident_id) REFERENCES incidents(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_admin (id INT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
